import Foundation

private func helpText(_ zh: String, _ en: String, _ ja: String) -> String {
    switch AppLanguage.current {
    case "zh-Hans": return zh
    case "ja": return ja
    default: return en
    }
}

enum SettingsHelpContent {
    /// Keep related sentences together while giving longer answers room to breathe.
    static func paragraphs(_ answer: String) -> [String] {
        let explicit = answer.components(separatedBy: "\n\n")
        if explicit.count > 1 { return explicit.filter { !$0.isEmpty } }
        var sentences: [String] = []
        answer.enumerateSubstrings(in: answer.startIndex..<answer.endIndex, options: .bySentences) { _, _, enclosingRange, _ in
            sentences.append(String(answer[enclosingRange]))
        }
        guard !sentences.isEmpty else { return [answer] }
        return stride(from: 0, to: sentences.count, by: 2).map { index in
            sentences[index..<min(index + 2, sentences.count)]
                .joined()
                .trimmingCharacters(in: .whitespacesAndNewlines)
        }
    }

    static var items: [(String, String)] {
        var items: [(String, String)] = []
        items.append((helpText("习惯与打卡", "Habits and check-ins", "習慣とチェックイン"), helpText("选择想培养的习惯，完成后打卡。每次完成都会推动对应植物成长。可以在设置中管理提醒。", "Choose the habits you want to build and check in when you complete them. Each completion helps its plant grow. Manage reminders in Settings.", "育てたい習慣を選び、完了したらチェックインします。完了するたびに対応する植物が成長します。通知は設定で管理できます。")))
        items.append((helpText("每天可以选择多少个习惯？", "How many habits can I select each day?", "1日に選べる習慣の数は？"), helpText("免费版每天可以选择 3 个普通或新加入的周期习惯；月付和年付都增加 2 个名额，也就是每天 5 个。星标习惯不占这些普通名额。周期习惯首次选择时占名额，在同一周期内继续保留时不再占当天新选名额。当天已完成的普通习惯仍计入当天额度。", "The free plan allows 3 regular habits or newly selected recurring habits per day. Monthly and yearly subscriptions both add 2 slots, for 5 per day. Starred habits do not use these regular slots. A recurring habit uses a slot when first selected; keeping it within the same period does not use a new daily slot. Regular habits completed today still count toward today's limit.", "無料プランでは、通常の習慣と新しく選んだ周期習慣を1日3個まで選べます。月額・年額プランではどちらも2枠増え、1日5個になります。星付き習慣はこの通常枠を使いません。周期習慣は初めて選ぶ日に枠を使い、同じ周期内に継続する場合は新しい当日枠を使いません。その日に完了した通常習慣も当日の上限に含まれます。")))
        items.append((helpText("什么时候可以使用星标？", "When can I use stars?", "星はいつ使えますか？"), helpText("首次确认习惯选择后，就可以在选择页面点卡片上的星标。起初可以设置 1 个；累计完成 6 次打卡后，可以设置 2 个。星标习惯会保留在选择中，不占普通名额；星标打卡不获得积分。星标位已满时，先取消一个已有星标，再设置新的星标。", "After confirming your first habit selection, tap the star on a card in the selection screen. You start with 1 star slot; after 6 total check-ins, you get 2. Starred habits stay selected and do not use regular slots; starred check-ins do not award points. If all star slots are in use, remove a star before adding another.", "最初の習慣選択を確定した後、選択画面のカードにある星をタップできます。最初は1個、チェックインを累計6回完了すると2個まで設定できます。星付き習慣は選択に残り、通常枠を使いません。星付きのチェックインではポイントは獲得できません。星枠がいっぱいの場合は、既存の星を外してから設定してください。")))
        items.append((helpText("月付和年付有什么区别？", "How do monthly and yearly plans differ?", "月額と年額の違いは？"), helpText("月付和年付都提供每天额外 2 个习惯名额、AI 周期复盘和 iCloud 同步。\n\n主要区别是：\n自定义卡片月付最多 2 张、年付最多 4 张；\n自定义任务月付每个订阅周期可创建 12 次、年付不限次数；\n庭院月付最多展示 14 株、年付最多展示 16 株。\n\n价格以 App Store 实际显示为准。", "Both plans add 2 daily habit slots and include AI periodic reviews and iCloud sync.\n\nThe main differences: monthly allows up to 2 custom cards, 12 custom task creations per subscription period and 14 plants displayed in the garden; yearly allows 4 cards, unlimited task creations and 16 plants.\n\nSee the App Store for current prices.", "どちらも習慣の1日あたりの枠が2つ増え、AIの定期振り返りとiCloud同期を利用できます。\n\n主な違いは、カスタムカードが月額2枚・年額4枚、カスタムタスクの作成が月額は契約期間ごとに12回・年額は無制限、庭の表示が月額14株・年額16株までという点です。\n\n価格はApp Storeの表示をご確認ください。")))
        items.append((helpText("植物如何成长？", "How do plants grow?", "植物はどう成長しますか？"), helpText("成长进度达到 3、10、25、60 时，植物依次进入发芽、成长、开花和繁茂阶段。", "At progress 3, 10, 25 and 60, a plant reaches sprout, growing, flowering and flourishing stages.", "成長の進捗が3、10、25、60に達すると、発芽、成長、開花、繁茂の段階に進みます。")))
        items.append((helpText("断签后会怎样？", "What happens if I miss days?", "チェックインを休むとどうなりますか？"), helpText("连续 7 个完整自然日没有任何打卡后，植物进入休眠，之后进度每天交替减少 1 或 2。再次打卡会暂停衰减；在 3 个不同的日子打卡后恢复正常。历史记录和已生成的卡片不会因此删除。", "After 7 full calendar days without any check-in, plants become dormant. Progress then falls by 1 and 2 on alternating days. Checking in pauses the decline; check in on 3 different days to recover. Past records and cards are kept.", "丸7日間チェックインがないと植物は休眠し、その後は進捗が1と2ずつ交互に減ります。再開すると減少が止まり、異なる3日間にチェックインすると回復します。過去の記録やカードは削除されません。")))
        items.append((helpText("免费版和订阅有什么区别？", "What does a subscription add?", "無料版とサブスクリプションの違いは？"), helpText("免费版可长期使用打卡、植物和历史记录。订阅增加 AI 周期复盘、更多自定义额度、庭院展示及 iCloud 同步。具体额度和价格以应用内显示为准。", "The free version includes check-ins, plants and history without a time limit. A subscription adds AI reviews, higher custom limits, more garden displays and iCloud sync. See the app for current limits and prices.", "無料版ではチェックイン、植物、履歴を期限なく利用できます。サブスクリプションではAI振り返り、カスタマイズ枠、庭の表示数、iCloud同期が追加されます。枠と価格はアプリ内をご確認ください。")))
        items.append((helpText("如何取消订阅或申请退款？", "How do I cancel or request a refund?", "解約や返金はどうすればよいですか？"), helpText("在 iPhone 的设置中，点按你的名字，再进入“订阅”并选择 MAYBII 取消。删除应用不会取消订阅。退款需向 Apple 申请，由 Apple 决定。", "On your iPhone, open Settings, tap your name, then Subscriptions and select MAYBII to cancel. Deleting the app does not cancel it. Request refunds from Apple; Apple makes the decision.", "iPhoneの設定で自分の名前をタップし、「サブスクリプション」からMAYBIIを選んで解約します。アプリを削除しても解約されません。返金はAppleに申請し、Appleが判断します。")))
        items.append((helpText("取消订阅后记录还在吗？", "Will I keep my records after cancelling?", "解約後も記録は残りますか？"), helpText("取消订阅不会删除本地打卡记录、植物、卡片和已生成的复盘。订阅权益到当前周期结束时停止。", "Cancelling does not delete local check-ins, plants, cards or existing reviews. Subscription benefits end when the current period expires.", "解約しても端末内のチェックイン、植物、カード、作成済みの振り返りは削除されません。特典は現在の期間の終了時に停止します。")))
        items.append((helpText("如何导出或同步记录？", "How do I export or sync records?", "記録の書き出しや同期は？"), helpText("设置中的“导出数据”可免费将记录整理成文件，通过系统分享保存。订阅用户可使用自己的 iCloud 同步；换设备时请使用同一个 Apple 账户并开启 iCloud。", "Use Export Data in Settings to save a file through the share sheet for free. Subscribers can sync using their own iCloud account. On a new device, use the same Apple account and enable iCloud.", "設定の「データを書き出す」から無料でファイルを保存できます。購読者は自分のiCloudで同期できます。新しい端末では同じAppleアカウントでサインインし、iCloudを有効にしてください。")))
        items.append((helpText("周复盘和月复盘的冷却规则是什么？", "How do weekly and monthly review cooldowns work?", "週・月の振り返りのクールダウンは？"), helpText("同一周的 AI 周复盘成功生成后，需要等 7 天才能为这一周重新生成；同一月的 AI 月复盘成功生成后，需要等 30 天才能为这一月重新生成。时间从成功生成时开始计算。周和月分别计算，不同的周或月也分别计算；切换语言不会重置同一周期的冷却。失败的请求不开始冷却。免费版可体验 1 次 AI 周复盘，AI 月复盘需要订阅。月复盘还需要所选月份有已完成的任务记录和可分析的文字。", "After a weekly AI review is generated successfully, wait 7 days before regenerating that same week's review. For the same month's AI review, wait 30 days. The timer starts on successful generation. Weekly and monthly reviews, and different weeks or months, have separate timers. Changing languages does not reset a period's timer. Failed requests do not start a cooldown. The free plan includes one AI weekly review; monthly AI reviews require a subscription. A monthly review also needs completed tasks and text to analyze in the selected month.", "同じ週のAI週次振り返りは、生成に成功してから7日後に再生成できます。同じ月のAI月次振り返りは30日後に再生成できます。時間は生成成功時から数えます。週と月、および異なる週や月の待ち時間は別々です。言語を変えても同じ期間の待ち時間はリセットされません。失敗したリクエストでは待ち時間は始まりません。無料プランではAI週次振り返りを1回体験でき、AI月次振り返りには購読が必要です。月次振り返りには、選択した月に完了済みのタスクと分析できる文章も必要です。")))
        items.append((helpText("AI 复盘会发送什么？", "What does AI Review send?", "AI振り返りでは何が送信されますか？"), helpText("使用 AI 复盘时，你选择的打卡记录和文字会经服务器发送给阿里云百炼的通义千问。首次发送前会征求同意；可在设置中撤回。", "AI Review sends the check-ins and text you select through our server to Alibaba Cloud Model Studio's Qwen. You are asked for consent before the first transmission and can withdraw it in Settings.", "AI振り返りでは、選択した記録と文章がサーバーを経由してAlibaba Cloudの通義千問に送信されます。初回送信前に同意を求め、設定で撤回できます。")))
        items.append((helpText("为什么采用订阅？", "Why a subscription?", "なぜサブスクリプションなのですか？"), helpText("AI 复盘需要持续使用模型和服务器，订阅用于支持这些持续服务。本地打卡、植物成长和历史记录仍可免费使用。", "AI reviews have ongoing model and server costs. Subscriptions support these services. Local check-ins, plant growth and history remain free.", "AI振り返りにはモデルとサーバーの継続費用がかかり、サブスクリプションはそのサービスを支えます。端末内のチェックイン、植物の成長、履歴は無料で利用できます。")))
        items.append((helpText("免费版是限时试用吗？", "Is the free plan a trial?", "無料版は期間限定ですか？"), helpText("不是。免费版可以长期使用核心打卡、植物和历史记录，并有一次 AI 周复盘体验；习惯名额和自定义额度有限。", "No. The free plan has no time limit for core check-ins, plants and history, and includes one AI weekly review. Habit and custom limits apply.", "いいえ。無料版のチェックイン、植物、履歴に利用期限はなく、AI週次振り返りを1回体験できます。習慣とカスタマイズの枠には上限があります。")))
        items.append((helpText("价格或权益以后会变化吗？", "Can prices or benefits change?", "価格や特典は変更されますか？"), helpText("已订阅周期内不涨价、不减少功能。将来如调整价格或权益，会提前在应用内和更新说明中公告；具体价格以 App Store 显示为准。", "Prices and benefits do not change during a paid period. Future changes will be announced in advance in the app and release notes. The App Store shows the actual price.", "支払い済み期間中は価格や機能を変更しません。将来変更する場合は、アプリ内と更新情報で事前にお知らせします。実際の価格はApp Storeをご確認ください。")))
        items.append((helpText("取消和退款有什么区别？", "How do cancellation and refunds differ?", "解約と返金の違いは？"), helpText("取消订阅是停止下次自动续费，当前周期通常继续有效；退款需要另行向 Apple 申请，由 Apple 审核。访问 reportaproblem.apple.com 可提交退款申请。退款或取消不会删除手机上的记录。", "Cancellation stops the next renewal; benefits generally continue until the period ends. A refund is a separate request reviewed by Apple. Apply at reportaproblem.apple.com. Neither cancellation nor a refund deletes records on your phone.", "解約は次回の自動更新を停止し、通常は現在の期間終了まで特典を利用できます。返金はAppleへの別途申請と審査が必要です。reportaproblem.apple.com から申請できます。解約や返金によって端末内の記録は削除されません。")))
        items.append((helpText("续费前怎样避免再次扣费？", "How can I avoid the next renewal charge?", "次回の更新請求を避けるには？"), helpText("订阅由 Apple 自动续费。若不想继续订阅，请至少在当前周期结束前 24 小时通过 iPhone 设置取消。收据和账单由 Apple 处理。", "Apple renews subscriptions automatically. To avoid renewal, cancel in iPhone Settings at least 24 hours before the current period ends. Apple handles billing and receipts.", "サブスクリプションはAppleが自動更新します。更新を避けるには、現在の期間が終わる24時間以上前にiPhoneの設定で解約してください。請求と領収書はAppleが管理します。")))
        items.append((helpText("如果应用停止运营，记录怎么办？", "What if the app is discontinued?", "アプリが終了したら記録はどうなりますか？"), helpText("如果停止运营，我们会提前公告，并保留 3 个月过渡期供你导出或截图保存记录。保存在手机里的记录不依赖我们的服务器，但仍请妥善保管设备及备份。", "If the app is discontinued, we will announce it in advance and provide a 3-month transition period to export or screenshot records. Records stored on your phone do not depend on our server; keep your device and backups safe.", "サービス終了時は事前にお知らせし、記録の書き出しやスクリーンショット保存のために3か月の移行期間を設けます。端末内の記録はサーバーに依存しませんが、端末とバックアップは大切に管理してください。")))
        items.append((helpText("AI 复盘的文字会被保存吗？", "Is my AI review text retained?", "AI振り返りの文章は保存されますか？"), helpText("复盘文字通过我们的服务器转发给通义千问。转发服务设计为仅在处理期间暂存，不把正文写入数据库或应用日志。生成的结果保存在设备上。阿里云可能根据法律及服务规则保存调用数据，具体范围和期限仍待核实；详情请查看隐私政策。", "Review text passes through our server to Qwen. The relay is designed to hold it only during processing and not write it to the database or app logs. Generated results are stored on your device. Alibaba Cloud may retain call data under law and service terms; scope and retention still need verification. See the privacy policy.", "振り返りの文章はサーバーを経由して通義千問に送られます。中継サービスは処理中のみ一時保持し、本文をデータベースやアプリログに書き込まない設計です。生成結果は端末に保存されます。Alibaba Cloudが法令や利用条件に基づきデータを保存する場合があり、その範囲と期間は確認中です。詳細はプライバシーポリシーをご覧ください。")))
        items.append((helpText("应用会一直运营和更新吗？", "Will the app keep running and receive updates?", "アプリは運営・更新され続けますか？"), helpText("无法承诺具体运营年限。核心打卡和本地记录不依赖服务器。若服务有重大变化或需要停止运营，我们会提前公告；更新和权益变化会在更新说明中解释。", "We cannot promise a specific number of years. Core check-ins and local records do not depend on the server. We will announce major service changes or discontinuation in advance and explain updates and benefit changes in release notes.", "具体的な運営年数はお約束できません。基本のチェックインと端末内の記録はサーバーに依存しません。大きな変更や終了は事前にお知らせし、更新や特典の変更は更新情報で説明します。")))
        items.append((helpText("如何联系我们？", "How can I contact you?", "問い合わせ方法は？"), helpText("使用设置中的“意见反馈”，或发送邮件至 deshiru@foxmail.com。我们会在 3 个工作日内回复。", "Use Feedback in Settings or email deshiru@foxmail.com. We reply within 3 business days.", "設定の「フィードバック」か deshiru@foxmail.com へご連絡ください。3営業日以内に返信します。")))
        return items
    }
}
